import sys, json, re, itertools, numpy as np, trimesh
sys.path.insert(0, "tools"); import geom
J = lambda n: json.load(open(f"build/{n}.json")); LY = J("layout"); B = LY["B"]; A = LY["A"]; FE = J("fea"); PS = J("printsim"); SH = J("shutter")
fe = lambda key, *has: [v for k, v in FE.items() if k.startswith(key) and all(h in k for h in has)][0]
d0 = B["BUMP"] - B["SCL"] - B["HUBC"]; K_BL = fe("blade click spring", "as drawn")["force_N"] / d0; K_WH = fe("wheel click spring", "as drawn")["force_N"] / d0
