# ------------------------------------------------------------------ 1. friction as a variable
MUS = (0.15, 0.25, 0.35, 0.45, 0.60); gain = lambda mu, m=1.0: (m + mu) / (1 - mu * m); wrap = np.radians(A["wrap_guide_deg"] + A["A_L"] + A["A_R"]); Rfull = A["ROLL_FULL"]; rows = []
from scadr import values; VW = values(["WH_Z", "RB_Z", "H", "SHAFT_R", "RB_GAP", "SLOT_Z", "COLLAR_Z", "KN_PZ", "KN_CZ", "KN_CR", "KN_R"])
NOSE = np.radians(A["wrap_roller_deg"][1]); LEAN = (VW["RB_Z"][0] - sum(VW["WH_Z"]) / 2) / (VW["H"] - VW["RB_Z"][0])    # the film's turn behind the gate (largest with a full take-up roll); the wheel's drum hangs 4 mm below its lower bearing, its two bearings are 9.5 mm apart
