for mu in MUS:
    g = np.exp(mu * wrap) * turn(mu); dt = PS["typical printer"]["blade"]["pushed_in"]; dn = PS["thin printer"]["blade"]["pushed_in"]
    rows.append(dict(mu=mu, shutter_click_typical_N=K_BL * dt * gain(mu) * RWB / R_F0, shutter_click_thin_N=K_BL * dn * gain(mu) * RWB / R_F0, aperture_click_N=K_WH * dt * gain(mu) * RWW / B["H_RHO"],
                     back_push_on_N=2 * kn * float(r_["name"].split("pushed down ")[1].split(" mm")[0]) * gain(mu, 0.6), plate_slide_on_N=kt * 1.35 * gain(mu, M_RAMP), film_path_gain=g, turn_gain=turn(mu), film_path_gain_with_a_free_roller=float(np.exp(mu * wrap)),
                     load_torque_typical_Nmm=1.0 * g * Rfull, load_torque_stiffest_Nmm=2.5 * g * Rfull, wind_torque_free_Nmm=(0.3 * g + 1.0) * Rfull, wind_torque_hand_on_other_knob_Nmm=(20 / 6.0 * g + 1.0) * Rfull))
