# ------------------------------------------------------------------ 3. the shutter in motion
def dynamics(mid=0.3):
    m = SH["blade_inertia_g_mm2"] * 1e-9 / (RWB * 1e-3) ** 2; mf = 10e-3 * (R_F / RWB) ** 2; S0 = TH * RWB; s_stop = S0 + np.radians(1.2) * RWB; rt = 0.7; grid = np.arange(-S0 - 2.5, S0 + 2.5, 0.004)
    def wall(s):
        g = np.zeros_like(s)
        for s0, D in ((-S0, B["BUMP"]), (0.0, mid), (S0, B["BUMP"])): g = np.maximum(g, np.clip(D - np.maximum(np.abs(s - s0) - 0.35, 0), 0, D))
        return g
    u = np.linspace(-rt, rt, 61); E = np.min(wall(grid[:, None] + u[None, :]) - np.sqrt(rt ** 2 - u[None, :] ** 2), axis=1); dE = np.gradient(E, grid)
    PRN = ["thin printer", "exact printer", "typical printer", "fattest printer"]; cases = list(itertools.product(PRN, (20.0, 50.0, 100.0, 200.0), (False, True), (0.3, 0.6), (0.2, 0.35, 0.5)))
    b = np.array([max(PS[c[0]]["blade"]["pushed_in"], 0.0) for c in cases]); vh = np.array([c[1] for c in cases]); flick = np.array([c[2] for c in cases]); er = np.array([c[3] for c in cases]); mu = np.array([c[4] for c in cases])
    n = len(cases); s = np.full(n, -S0); v = np.zeros(n); gone = np.zeros(n, bool); dt = 2e-6; kf = 0.5; throw = 2 * PX * np.sin(TH); ZF0 = PX * np.sin(TH) + PZ * np.cos(TH); s_half = 2.8 * RWB / R_PORT; s_light = (2.8 + 1.75) * RWB / R_PORT
    t_exp = np.zeros(n); passed = np.zeros(n, bool); t_re = np.zeros(n); back = np.zeros(n)
    for i in range(int(0.45 / dt)):
        t = i * dt; Ei = np.interp(s, grid, E); d = np.maximum(0, b - rt - Ei); dd = np.where(d > 0, -np.interp(s, grid, dE), 0.0); Fs = -K_BL * d * dd
        psi = -s / RWB; lev = PX * np.cos(psi) - PZ * np.sin(psi); xt = ZF0 - (PX * np.sin(psi) + PZ * np.cos(psi)); gone |= flick & (xt > 0.5 * throw); push = np.where(gone | (t > 0.4), 0.0, np.maximum(0, kf * (np.minimum(vh * t, throw + 1.5) - xt))); F0 = push * lev / RWB + Fs; Ff = mu * K_BL * d + 0.003      # (a held finger lets go after 0.4 s)
