        vn = np.where(mov & (np.sign(vn) != np.sign(v)) & (np.abs(F0) <= Ff), 0.0, vn); s = s + vn * dt; hit = (s > s_stop) & (vn > 0); vn = np.where(hit, -er * vn, vn); s = np.minimum(s, s_stop); lo = (s < -s_stop) & (vn < 0); vn = np.where(lo, -er * vn, vn); s = np.maximum(s, -s_stop); v = vn
